"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[892],{401:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>hw-01-tools-data</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="домашняя-работа-1-пропуски-и-кодирование-категорий">Домашняя\nработа 1. Пропуски и кодирование категорий</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<tbody>\n<tr>\n<td>К семинару</td>\n<td>занятие 1 — Инструменты, данные и первый ориентир</td>\n</tr>\n<tr>\n<td>Опора</td>\n<td>материал семинара 1 и лекций до него</td>\n</tr>\n<tr>\n<td>Ожидаемое время</td>\n<td>3–4 часа</td>\n</tr>\n</tbody>\n</table>\n<p>На занятии мы заполняли пропуски медианой, а категории кодировали\n<code>OneHotEncoder</code>&#39;ом — обоими способами «как принято». Дома\nразберёмся, почему принято именно так и когда это ломается.\\n\\nРабота\nопирается на ту же индивидуальную таблицу, что и семинар.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук, в котором:</p>\n<ol>\n<li>выполнены все ячейки с <code># TODO</code>, код исполняется сверху\nвниз без ошибок в свежем ядре (Kernel → Restart &amp; Run All);</li>\n<li>под каждым заданием заполнена ячейка <strong>Вывод</strong> — своими\nсловами;</li>\n<li>графики подписаны: заголовок, оси, легенда;</li>\n<li>вариант ваш собственный (ячейка ниже).</li>\n</ol>\n<blockquote>\n<p>Списывание видно сразу: у каждого студента свой датасет и свой набор\nметодов.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> make_table</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Готовим таблицу теми же шагами, что и на занятии</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> clean_table</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>df_raw, meta <span class="op">=</span> make_table(variant)</span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a>df <span class="op">=</span> clean_table(df_raw, meta)</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a>TASK, TARGET <span class="op">=</span> meta[<span class="st">&quot;task&quot;</span>], meta[<span class="st">&quot;target&quot;</span>]</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>meta[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>df<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss"> объектов, </span><span class="sc">{</span>df<span class="sc">.</span>shape[<span class="dv">1</span>] <span class="op">-</span> <span class="dv">1</span><span class="sc">}</span><span class="ss"> признаков&quot;</span>)</span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;пропусков по столбцам:&quot;</span>)</span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(df.isna().<span class="bu">sum</span>()[df.isna().<span class="bu">sum</span>() <span class="op">&gt;</span> <span class="dv">0</span>])</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="задача-1-заполнение-пропусков-с-учётом-механизма">Задача 1.\nЗаполнение пропусков с учётом механизма</h1>\n<p>Мало посчитать долю пропусков — важно понять, <strong>почему</strong>\nзначение отсутствует:</p>\n<ul>\n<li><strong>MCAR</strong> — пропуск не зависит ни от чего;</li>\n<li><strong>MAR</strong> — вероятность пропуска зависит от <em>других\nнаблюдаемых</em> признаков (доход чаще не указывают клиенты с малым\nстажем);</li>\n<li><strong>MNAR</strong> — зависит от самого пропущенного значения (не\nуказывают именно большие доходы). Худший случай: по данным его не\nотличить.</li>\n</ul>\n<p>Разница практическая: при MAR заполнение общей медианой\nсистематически искажает признак. Сейчас измерим, насколько.</p>\n</div>\n<div id="cell006" class="cell markdown">\n<h3 id="задание-11-найти-столбец-с-mar-и-его-драйвер">Задание 1.1. Найти\nстолбец с MAR и его драйвер</h3>\n<p>Для каждого числового столбца с пропусками найдите признак, сильнее\nвсего связанный с <em>фактом</em> пропуска. Мера связи: модуль разности\nсредних в группах «значение есть» и «значение пропущено», в единицах\nстандартного отклонения.</p>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>num_cols <span class="op">=</span> [c <span class="cf">for</span> c <span class="kw">in</span> df.select_dtypes(include<span class="op">=</span><span class="st">&quot;number&quot;</span>).columns <span class="cf">if</span> c <span class="op">!=</span> TARGET]</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>with_na <span class="op">=</span> [c <span class="cf">for</span> c <span class="kw">in</span> num_cols <span class="cf">if</span> df[c].isna().<span class="bu">any</span>()]</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждой пары (столбец с пропусками, другой числовой признак)</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       посчитайте |mean(есть) - mean(пропуск)| / std(признака)</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       и соберите таблицу, отсортированную по убыванию этой величины.</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>link <span class="op">=</span> ...</span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>display(link.head(<span class="dv">8</span>).<span class="bu">round</span>(<span class="dv">3</span>))</span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: верхняя строка -- искомая пара</span></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a>MAR_COL, DRIVER <span class="op">=</span> ..., ...</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<h3 id="задание-12-два-способа-заполнения">Задание 1.2. Два способа\nзаполнения</h3>\n<p>Заполните пропуски в <code>MAR_COL</code> двумя способами — общей\nмедианой и медианой внутри квартилей драйвера (напомним: квартили — это\nквантили уровней 0.25, 0.5 и 0.75, они делят выборку на четыре равные по\nчисленности группы) — и сравните каждый результат с эталоном:\nраспределением значений на объектах, где значение известно.</p>\n<p>Мера близости — статистика Колмогорова–Смирнова\n(<code>scipy.stats.ks_2samp</code>): максимальное расхождение\nэмпирических функций распределения.</p>\n</div>\n<div id="cell009" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> stats</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>known <span class="op">=</span> df.loc[df[MAR_COL].notna(), MAR_COL]</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>flag <span class="op">=</span> df[MAR_COL].isna()</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (а) filled_global -- заполнить общей медианой;</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       (б) filled_grouped -- медианой внутри квартилей драйвера</span></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="co">#           (pd.qcut(df[DRIVER], q=4) и groupby(...).transform(&quot;median&quot;)).</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждого способа посчитайте stats.ks_2samp(заполненные, known)</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       и сведите в таблицу вместе со средним и стандартным отклонением.</span></span></code></pre></div>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте гистограммы: известные значения и оба варианта заполнения.</span></span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой способ дал меньшую статистику\nКолмогорова–Смирнова? Что происходит с дисперсией признака при\nзаполнении константой и чем это опасно?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="задача-2-своя-реализация-one-hot-кодирования">Задача 2. Своя\nреализация One-Hot кодирования</h1>\n<p>Категориальный признак нельзя подать в модель как есть, а нумерация\nкатегорий подряд навязывает несуществующий порядок. Стандартное решение\n— индикаторы: по столбцу на каждую категорию.</p>\n<p>Реализуйте кодировщик сами и разберитесь, зачем нужен\n<code>drop=&#39;first&#39;</code>.</p>\n</div>\n<div id="cell013" class="cell markdown">\n<h3 id="задание-21-функция-one_hot">Задание 2.1. Функция\n<code>one_hot</code></h3>\n<p><code>one_hot(series, categories=None)</code> возвращает матрицу\nиндикаторов и список категорий. Если <code>categories</code> задан\nизвне, незнакомые значения кодируются <strong>нулевой строкой</strong> —\nтак ведёт себя <code>handle_unknown=&#39;ignore&#39;</code>. Это важно: на\nконтроле может встретиться категория, которой не было в обучении, а\nширина матрицы обязана сохраниться.</p>\n</div>\n<div id="cell014" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> one_hot(series, categories<span class="op">=</span><span class="va">None</span>):</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Индикаторное кодирование. Возвращает (матрица (n, k), список категорий).&quot;&quot;&quot;</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: 1) если categories не задан -- отсортированные уникальные значения без NaN;</span></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">#       2) матрица нулей (n, len(categories));</span></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">#       3) для каждого объекта поставить 1 в столбец своей категории;</span></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    <span class="co">#          незнакомое значение и NaN оставить нулевой строкой.</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> OneHotEncoder</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>cat_col <span class="op">=</span> meta[<span class="st">&quot;categorical&quot;</span>][<span class="dv">0</span>]</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>known_cat <span class="op">=</span> df[cat_col].dropna()</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>train, test <span class="op">=</span> known_cat.iloc[: <span class="bu">len</span>(known_cat) <span class="op">//</span> <span class="dv">2</span>], known_cat.iloc[<span class="bu">len</span>(known_cat) <span class="op">//</span> <span class="dv">2</span>:]</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: закодируйте train (категории из данных) и test (категории из train),</span></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       сверьте обе матрицы с OneHotEncoder(handle_unknown=&quot;ignore&quot;),</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       проверьте, что незнакомое значение и NaN дают нулевые строки.</span></span></code></pre></div>\n</div>\n<div id="cell016" class="cell markdown">\n<h3 id="задание-22-зачем-dropfirst">Задание 2.2. Зачем\n<code>drop=&#39;first&#39;</code></h3>\n<p>Сумма всех индикаторов по строке равна единице — то есть совпадает со\nстолбцом свободного члена. Значит, столбцы линейно зависимы и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nвырождена.</p>\n<p>Убедитесь численно: соберите «столбец единиц + полный One-Hot»,\nпосмотрите ранг и число обусловленности, затем повторите с отброшенной\nпервой категорией.</p>\n</div>\n<div id="cell017" class="cell markdown">\n<blockquote>\n<p><strong>Напоминание — число обусловленности.</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>σ</mi><mi>max</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mi>/</mi><msub><mi>σ</mi><mi>min</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(A) = \\sigma_{\\max}(A)/\\sigma_{\\min}(A)</annotation></semantics></math>\n— отношение наибольшего сингулярного числа к наименьшему (для\nсимметричной положительно определённой матрицы — отношение собственных\nчисел). Смысл простой: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mn>10</mn><mi>k</mi></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(A) = 10^{k}</annotation></semantics></math>,\nто при решении системы с матрицей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>\nтеряется примерно\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nверных десятичных знаков. У вырожденной матрицы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>σ</mi><mi>min</mi></msub><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma_{\\min} = 0</annotation></semantics></math>,\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo>=</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\mathrm{cond} = \\infty</annotation></semantics></math>;\nзначение порядка\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mn>10</mn><mn>16</mn></msup><annotation encoding="application/x-tex">10^{16}</annotation></semantics></math>\nна компьютере означает «практически вырождена». В NumPy:\n<code>np.linalg.cond(A)</code>. Величина встретится ещё много раз — в\nзанятиях 2, 3 и 9.</p>\n</blockquote>\n</div>\n<div id="cell018" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) A_full = [столбец единиц | полный One-Hot],</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a><span class="co">#          A_drop = [столбец единиц | One-Hot без первого столбца];</span></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) для каждой выведите число столбцов, ранг и cond(A^T A);</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) покажите, что сумма индикаторов по строке равна 1;</span></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) постройте два РАЗНЫХ вектора весов с одинаковым прогнозом на A_full</span></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          (прибавьте c к свободному члену и вычтите c из индикаторов).</span></span></code></pre></div>\n</div>\n<div id="cell019" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Чему равен ранг в каждом случае и как\nменяется обусловленность? Почему для решающего дерева этой проблемы не\nвозникает?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell020" class="cell markdown">\n<h2 id="итоги-домашней-работы">Итоги домашней работы</h2>\n<p>Кратко ответьте на вопросы:</p>\n<ol>\n<li>Коллега заполнил пропуски средним по всей выборке — включая\nконтрольную часть. Какие два разных дефекта он допустил\nодновременно?</li>\n<li>В обучающей выборке признак «регион» принимает 40 значений, в\nконтрольной встретилось 41-е. Что произойдёт при\n<code>handle_unknown=&#39;ignore&#39;</code> и чем это лучше падения с\nошибкой?</li>\n</ol>\n<hr />\n<p>Проверьте перед сдачей: Kernel → Restart &amp; Run All проходит без\nошибок, все ячейки <strong>Вывод</strong> заполнены, графики\nподписаны.</p>\n</div>\n</body>\n</html>\n'}}]);